package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}
 * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased
 * first three letters of the last name and NNNN is a per-city 4-digit zero-padded
 * sequence equal to one more than the number of owners already in that city (e.g.
 * {@code SYD-SMI-0007}). Runs before the owner is saved, so the count excludes the owner
 * being created and successive creates in the same city receive consecutive sequence
 * numbers.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city = owner.getCity();
        String city3 = first3(city);
        String last3 = first3(owner.getLastName());
        int sequence = 1;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equalsIgnoreCase(existing.getCity())) {
                sequence++;
            }
        }
        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
    }

    /** Upper-cased first three letters of {@code value} (fewer if it is shorter). */
    private static String first3(String value) {
        return value.substring(0, Math.min(3, value.length())).toUpperCase();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Resolves the effective registration date and rolls it onto a business day. The effective
 * date is the request-supplied {@code registrationDate} when present, otherwise the
 * server's current date; when that date falls on a Saturday or Sunday it rolls forward to
 * the following Monday. The resolved business-day date is published so the steps that count
 * owners per day, stamp the owner and derive the membership number all use the same
 * adjusted value.
 */
public class ResolveRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate effective = request.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        registrationDate.set(toBusinessDay(effective));
    }

    /** Rolls a weekend date forward to the following Monday; a business day is unchanged. */
    static LocalDate toBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        if (day == DayOfWeek.SATURDAY) {
            return date.plusDays(2);
        }
        if (day == DayOfWeek.SUNDAY) {
            return date.plusDays(1);
        }
        return date;
    }
}

